function normalizeText(v) {
  return String(v || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// IMPORTANT:
// no new URL() here.
// Accepts:
// linkedin.com/in/name
// www.linkedin.com/in/name/
// pt.linkedin.com/in/name
// pt.linkedin.com/in/name/en
// de.linkedin.com/in/name/de
function normalizeLinkedInProfile(rawUrl) {
  if (!rawUrl) return null;

  let url = String(rawUrl).trim();

  // Remove query/hash
  url = url.split('#')[0].split('?')[0];

  // Add scheme only for easier regex consistency
  if (!/^https?:\/\//i.test(url)) {
    url = 'https://' + url;
  }

  const match = url.match(
    /^https?:\/\/(?:[a-z]{2,3}\.)?(?:www\.)?linkedin\.com\/in\/([^\/?#]+)(?:\/(?:[a-z]{2}(?:-[a-z]{2})?))?\/?$/i
  );

  if (!match || !match[1]) {
    return null;
  }

  const slug = match[1].trim();

  if (!slug) {
    return null;
  }

  return `https://www.linkedin.com/in/${slug}/`;
}

