  const rawUrl = result?.url || null;
  const linkedinUrl =
    normalizeLinkedInProfile(rawUrl);

  if (!linkedinUrl) {
    rejected.push({
      url: rawUrl,
      reason: 'NOT_LINKEDIN_PROFILE_URL'
    });
    continue;
  }

  const titleText =
    normalizeText(result?.title || '');

  const contentText =
    normalizeText(result?.content || '');

  const evidenceText =
    `${titleText} ${contentText}.trim()`;

  const nameMatch =
    nameTokens.length >= 2 &&
    nameTokens.every(token =>
      evidenceText.includes(token)
    );

  const companyMatch =
    !!expectedCompany &&
    evidenceText.includes(expectedCompany);

  const titleMatch =
    titleTokens.length > 0 &&
    titleTokens.some(token =>
      evidenceText.includes(token)
    );

  if (!nameMatch) {
    rejected.push({
      url: rawUrl,
      normalized_url: linkedinUrl,
      reason: 'NAME_MISMATCH'
    });
    continue;
  }

  // Require company OR title corroboration.
  if (!companyMatch && !titleMatch) {
    rejected.push({
      url: rawUrl,
      normalized_url: linkedinUrl,
      reason: 'NO_EMPLOYER_OR_TITLE_CORROBORATION'
    });
    continue;
  }

  candidates.push({
    linkedin_url: linkedinUrl,
    source_url: rawUrl,
    name_match: nameMatch,
    company_match: companyMatch,
    title_match: titleMatch,
    search_title: result?.title || null,
    search_snippet: result?.content || null,
