function casefold(s){ return String(s).toLowerCase().replace(/\u00df/g,'ss').replace(/\u03c2/g,'\u03c3'); }
function ndom(d){ return String(d||'').trim().toLowerCase().replace(/\.$/,''); }
function nname(s){ if(s==null||s==='') return ''; let x=String(s).normalize('NFKD'); x=x.replace(/\p{M}/gu,''); x=casefold(x); x=x.replace(/['\u2019\u02bc\u2018]/gu,''); x=x.replace(/\p{P}/gu,' '); x=x.replace(/[^\p{L}\p{N}\s]/gu,' '); x=x.replace(/\s+/gu,' '); return x.trim(); }
function nurl(u){ if(u==null||u==='') return ''; return String(u).trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/[?#].*$/,'').replace(/\/+$/,''); }
function ncompany(s){ if(s==null||s==='') return ''; let x=String(s).normalize('NFKC'); x=casefold(x); x=x.replace(/\p{P}/gu,' '); x=x.replace(/[^\p{L}\p{N}\s]/gu,' '); x=x.replace(/\s+/gu,' '); return x.trim(); }
function nameCompare(a,b){
  const na=nname(a), nb=nname(b);
  if(!na||!nb) return 'UNUSABLE';
  if(na===nb) return 'CONSISTENT';
  const ta=na.split(' '), tb=nb.split(' ');
  if(ta.length===tb.length && ta.length>1 && JSON.stringify([...ta].sort())===JSON.stringify([...tb].sort())) return 'UNUSABLE';
  if(ta.length>=2 && tb.length>=2 && ta[0]===tb[0] && ta[ta.length-1]===tb[tb.length-1]){
    const ma=ta.slice(1,-1), mb=tb.slice(1,-1);
    if(ma.length===0 || mb.length===0) return 'CONSISTENT';
    if(ma.length!==mb.length) return 'UNUSABLE';
    for(let i=0;i<ma.length;i++){
      const a=ma[i], b=mb[i];
      if(a===b) continue;
      if(a.length===1 && b.startsWith(a)) continue;
      if(b.length===1 && a.startsWith(b)) continue;
      return 'UNUSABLE';
    }
    return 'CONSISTENT';
  }
  if(ta.length>=2 && tb.length>=2 && ta[0]!==tb[0] && ta[ta.length-1]!==tb[tb.length-1]) return 'CONFLICT';
  return 'UNUSABLE';
}

